import { cloudflare } from '@cloudflare/vite-plugin';
import { flue, flueWorkerConfig } from '@flue/vite';
import { defineConfig } from 'vite';

import { localIntelligenceWorkerEnvironment } from '../../scripts/local-development.mjs';

export default defineConfig(({ command }) => {
	const fluePlugin = flue();
	const configureFlueWorker = flueWorkerConfig();

	return {
		// The worker entry is virtual (generated by @flue/vite), so Vite's dep
		// scanner finds nothing up front and every dependency is discovered
		// lazily at first import. Each discovery re-bundles the optimizer
		// output and renames its content-hashed chunks, but the workerd module
		// runner keeps evaluating modules that import the old chunk names --
		// startup dies on a missing `mcp-*` chunk from @flue/runtime. Seeding
		// the full dependency set makes the first optimizer pass complete, so
		// nothing is renamed under the runner. This must live on the worker
		// environment (named after the wrangler worker, dashes as
		// underscores); top-level optimizeDeps only reaches the client.
		environments: {
			code2create_intelligence: {
				optimizeDeps: {
					include: [
						'@earendil-works/pi-ai/providers/openai',
						'@flue/runtime',
						'@flue/runtime/cloudflare',
						'@flue/runtime/cloudflare/internal',
						'@flue/runtime/internal',
						'hono',
						'valibot',
					],
				},
			},
		},
		plugins: [
			fluePlugin,
			cloudflare({
				config(config) {
					configureFlueWorker(config);
					if (command !== 'serve') return;
					return {
						vars: {
							...config.vars,
							...localIntelligenceWorkerEnvironment,
						},
					};
				},
				inspectorPort: 9238,
			}),
		],
	};
});
